def fetch_with_retry(fetch_fn, attempts=3):
    for attempt in range(attempts):
        try:
            return fetch_fn()
        except (ConnectionError, TimeoutError) as e:
            print(f"Attempt {attempt + 1} failed: {e}, retrying...")
    raise RuntimeError("All attempts failed")
